-- 228 (17/11/2026, lô 55): « DELF B1 · Đề 3 », phần ĐỌC viết lại khó hơn (văn bản dài hơn, câu hỏi về hàm ý).
-- Sinh bởi scripts/nhap/lo55_kho.mjs --cap B1 --de 3. Sửa thẳng, giữ id bài và id câu (cập nhật theo ord). Chạy lại an toàn.
-- lo18mv42gok004n
update public.exercises set consigne = '<p>Vous voulez suivre un cours le soir ou le week-end. Lisez les annonces et répondez aux questions.</p>', reading_text = '<p><strong>A. Photo numérique</strong> : le mardi de 19 h à 21 h, dix séances. Apprenez à régler votre appareil, à composer une image et à travailler la lumière. Apporter son propre appareil : les téléphones ne sont pas acceptés. 120 € le cycle, paiement à l''inscription. Sortie photo en ville le dernier dimanche, pour ceux qui le souhaitent. Une exposition des meilleurs travaux est organisée à la fin du cycle.</p><p><strong>B. Espagnol débutant</strong> : le lundi et le jeudi à 18 h 30, entièrement en ligne, en petits groupes de six. 90 € le trimestre. Un ordinateur avec caméra et micro est indispensable. Un test gratuit de vingt minutes permet de vérifier votre niveau avant l''inscription. Les cours enregistrés restent disponibles pendant une semaine.</p><p><strong>C. Théâtre amateur</strong> : le mercredi à 20 h, salle Molière. Exercices de voix, improvisation, puis préparation d''une pièce présentée au public en juin. 150 € l''année. Les répétitions supplémentaires de mai sont obligatoires pour participer au spectacle.</p><p><strong>D. Cuisine du monde</strong> : le vendredi à 19 h, quatre participants maximum pour que chacun cuisine vraiment. Chaque mois, un pays différent. 35 € la séance, ingrédients compris ; on repart avec ce qu''on a préparé. Réservation au moins une semaine à l''avance. Signalez vos allergies au moment de l''inscription.</p><p><strong>E. Yoga doux</strong> : le samedi à 9 h, adapté aux débutants et aux personnes qui ont mal au dos. Premier cours gratuit, ensuite 8 € la séance ou 70 € la carte de dix. Tapis prêtés, mais pensez à apporter une serviette et une bouteille d''eau.</p>' where id = 'lo18mv42gok004n';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'qcm', 'Vous voulez apprendre depuis chez vous et connaître votre niveau avant de payer. Vous choisissez…', '{"options":["B","A","D"]}'::jsonb, '{"answer":0}'::jsonb, 'B: « entièrement en ligne » và « Un test gratuit de vingt minutes permet de vérifier votre niveau ».'),
  (2, 'qcm', 'Vous voulez essayer gratuitement une activité physique douce. Vous choisissez…', '{"options":["A","C","E"]}'::jsonb, '{"answer":2}'::jsonb, 'E: « Premier cours gratuit », « adapté aux débutants et aux personnes qui ont mal au dos ».'),
  (3, 'qcm', 'Vous aimez cuisiner en très petit groupe et rapporter votre repas. Vous choisissez…', '{"options":["D","B","C"]}'::jsonb, '{"answer":0}'::jsonb, 'D: « quatre participants maximum » và « on repart avec ce qu''on a préparé ».'),
  (4, 'qcm', 'Quel cours oblige à venir en dehors de l''horaire habituel ?', '{"options":["E","A","C"]}'::jsonb, '{"answer":2}'::jsonb, 'C: « Les répétitions supplémentaires de mai sont obligatoires ». Buổi chụp ảnh ngoài phố của A không ghi là bắt buộc.'),
  (5, 'qcm', 'Dans le cours de photo, on ne peut pas…', '{"options":["suivre le cours le mardi.","utiliser un téléphone.","participer à une sortie en ville."]}'::jsonb, '{"answer":1}'::jsonb, '« les téléphones ne sont pas acceptés ».')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo18mv42gok004n' and q.ord = v.ord;

-- lo18mv42gok004o
update public.exercises set consigne = '<p>Lisez l''article puis répondez aux questions.</p>' where id = 'lo18mv42gok004o';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'qcm', 'Quelle situation l''article décrit-il au début ?', '{"options":["Des jeunes toujours connectés qui ne décrochent pas.","Des adolescents qui n''ont plus de forfait téléphonique.","Des parents qui refusent de donner un téléphone à leurs enfants."]}'::jsonb, '{"answer":0}'::jsonb, '« Les adolescents ont un téléphone greffé à la main… mais ne répondent pas quand on les appelle ».'),
  (2, 'vf', 'Chez les adolescents, l''appel vocal reste le moyen de communication habituel.', '{}'::jsonb, '{"answer":1,"justification":"Chez les adolescents, l’appel vocal n’est plus le canal par défaut"}'::jsonb, null),
  (3, 'qcm', 'Dans quel cas un adolescent accepte-t-il encore d''appeler ?', '{"options":["quand il a besoin d''être rassuré tout de suite","quand il doit organiser une sortie avec plusieurs amis","quand il n''a plus de batterie"]}'::jsonb, '{"answer":0}'::jsonb, 'Cuộc gọi dành cho « situations urgentes, moments d’angoisse, besoin d’un réconfort immédiat ».'),
  (4, 'qcm', 'D''après l''auteure, pourquoi les adolescents préfèrent-ils écrire ?', '{"options":["Ils sont trop paresseux pour parler.","Les appels coûtent plus cher que les messages écrits.","L''écrit leur laisse le temps de choisir leurs mots."]}'::jsonb, '{"answer":2}'::jsonb, '« Non pas par paresse », mà vì « On peut formuler, reformuler, supprimer, différer ».'),
  (5, 'vf', 'Répondre tout de suite au téléphone peut donner aux adolescents l''impression de perdre le contrôle.', '{}'::jsonb, '{"answer":0,"justification":"cette immédiateté est perçue comme un stress, une perte de contrôle"}'::jsonb, null),
  (6, 'qcm', 'Que montre le « petit rituel » cité dans l''article ?', '{"options":["Ils utilisent Snapchat seulement pour jouer.","Ils n''aiment plus parler à leurs amis.","Il est poli de demander avant d''appeler."]}'::jsonb, '{"answer":2}'::jsonb, '« sonder l’autre avant de se lancer dans un appel, devient une preuve de respect ».'),
  (7, 'qcm', 'Que propose l''auteure aux familles ?', '{"options":["discuter des préférences de chacun","interdire les messages pendant les repas","obliger les adolescents à répondre à tous les appels"]}'::jsonb, '{"answer":0}'::jsonb, '« une discussion franche et tranquille sur les préférences de chacun en matière de communication ».'),
  (8, 'qcm', 'Comment l''auteure voit-elle ce « silence téléphonique » ?', '{"options":["comme le signe d''une crise grave","comme une occasion de changer nos habitudes","comme un simple caprice d''adolescent"]}'::jsonb, '{"answer":1}'::jsonb, '« pourquoi ne pas y lire une occasion de réinventer nos façons de se parler ? ».')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo18mv42gok004o' and q.ord = v.ord;
